//! Independent reference values for Box-Cox and the censored fits.
//!
//! `tests/reference/reliability.json` is generated by
//! `tools/gen_reliability.py` (scipy profile and lifelines); the test never
//! runs Python.

use fp_core::boxcox;
use fp_core::data::{Column, DataFrame, MissingPolicy, Sample};
use fp_core::reliability;
use serde_json::Value;

fn reference() -> Value {
    let raw = include_str!("reference/reliability.json");
    serde_json::from_str(raw).expect("valid JSON reference")
}

fn numbers(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .expect("number list")
        .iter()
        .map(|value| value.as_f64().expect("number"))
        .collect()
}

fn close(actual: f64, expected: f64, tolerance: f64, what: &str) {
    assert!(
        (actual - expected).abs() <= tolerance * (1.0 + expected.abs()),
        "{what}: {actual} vs oracle {expected}"
    );
}

fn frame(case: &Value) -> DataFrame {
    let times = numbers(&case["times"]);
    let censor = numbers(&case["censor"]);
    DataFrame::new(vec![
        Column::new_f64("time", times),
        Column::new_f64("censor", censor),
    ])
    .expect("frame")
}

#[test]
fn boxcox_lambda_and_interval_match_the_scipy_profile() {
    let r = reference();
    let case = &r["boxcox"];
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let sample = Sample::new(numbers(&case["data"]), MissingPolicy::Drop).expect("sample");
    close(
        boxcox::lambda(&sample).expect("lambda"),
        case["lambda"].as_f64().expect("lambda"),
        tolerance,
        "Box-Cox lambda",
    );
    let interval = boxcox::lambda_interval(&sample, 0.95).expect("interval");
    let expected = numbers(&case["interval"]);
    close(interval.0, expected[0], tolerance, "Box-Cox lower");
    close(interval.1, expected[1], tolerance, "Box-Cox upper");
}

#[test]
fn censored_weibull_matches_lifelines() {
    let r = reference();
    let case = &r["weibull"];
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    // The parameters agree to the optimiser tolerance (1e-4); the likelihood
    // and the AIC agree to the file tolerance.
    let parameter_tolerance = 1e-4;
    let model = reliability::fit_weibull(&frame(&r), "time", Some("censor"), 1.0)
        .expect("censored weibull");
    close(
        model.shape,
        case["shape"].as_f64().expect("shape"),
        parameter_tolerance,
        "shape",
    );
    close(
        model.scale,
        case["scale"].as_f64().expect("scale"),
        parameter_tolerance,
        "scale",
    );
    close(
        model.log_likelihood,
        case["log_likelihood"].as_f64().expect("llf"),
        tolerance,
        "log-likelihood",
    );
    close(
        model.aic,
        case["aic"].as_f64().expect("aic"),
        tolerance,
        "AIC",
    );
    let ci = &case["ci"];
    let expected = numbers(&ci["shape"]);
    let interval = model.shape_ci.expect("shape interval");
    close(interval.0, expected[0], 1e-4, "shape lower");
    close(interval.1, expected[1], 1e-4, "shape upper");
    let expected = numbers(&ci["scale"]);
    let interval = model.scale_ci.expect("scale interval");
    close(interval.0, expected[0], 1e-4, "scale lower");
    close(interval.1, expected[1], 1e-4, "scale upper");
    let expected = numbers(&ci["b10"]);
    let interval = model.b10_ci.expect("B10 interval");
    close(interval.0, expected[0], 1e-4, "B10 lower");
    close(interval.1, expected[1], 1e-4, "B10 upper");
    assert_eq!(model.n, 15);
    assert_eq!(model.events, 11);
    assert_eq!(model.censored, 4);
}

#[test]
fn censored_lognormal_matches_lifelines() {
    let r = reference();
    let case = &r["lognormal"];
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let parameter_tolerance = 1e-4;
    let model = reliability::fit_lognormal(&frame(&r), "time", Some("censor"), 1.0)
        .expect("censored lognormal");
    close(
        model.mu,
        case["mu"].as_f64().expect("mu"),
        parameter_tolerance,
        "mu",
    );
    close(
        model.sigma,
        case["sigma"].as_f64().expect("sigma"),
        parameter_tolerance,
        "sigma",
    );
    close(
        model.log_likelihood,
        case["log_likelihood"].as_f64().expect("llf"),
        tolerance,
        "log-likelihood",
    );
    close(
        model.aic,
        case["aic"].as_f64().expect("aic"),
        tolerance,
        "AIC",
    );
    let ci = &case["ci"];
    let expected = numbers(&ci["mu"]);
    let interval = model.mu_ci.expect("mu interval");
    close(interval.0, expected[0], 1e-4, "mu lower");
    close(interval.1, expected[1], 1e-4, "mu upper");
    let expected = numbers(&ci["sigma"]);
    let interval = model.sigma_ci.expect("sigma interval");
    close(interval.0, expected[0], 1e-4, "sigma lower");
    close(interval.1, expected[1], 1e-4, "sigma upper");
    let expected = numbers(&ci["b10"]);
    let interval = model.b10_ci.expect("B10 interval");
    close(interval.0, expected[0], 1e-4, "B10 lower");
    close(interval.1, expected[1], 1e-4, "B10 upper");
}

#[test]
fn a_constant_time_column_is_rejected() {
    let df = DataFrame::new(vec![
        Column::new_f64("time", vec![5.0; 8]),
        Column::new_f64("censor", vec![0.0; 8]),
    ])
    .expect("frame");
    assert!(reliability::fit_weibull(&df, "time", Some("censor"), 1.0).is_err());
}
